<script setup>
import {computed,ref} from 'vue';const props=defineProps({content:String});const expanded=ref(false);const long=computed(()=>props.content.length>500);const shown=computed(()=>long.value&&!expanded.value?props.content.slice(0,420)+'…':props.content);const lines=computed(()=>shown.value.split('\n').filter(l=>l.trim()).map(line=>({bullet:/^[-•]\s/.test(line),text:line.replace(/^[-•]\s/,'').replace(/^#{1,4}\s/,'').split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map(s=>({bold:s.startsWith('**')&&s.endsWith('**'),text:s.startsWith('**')&&s.endsWith('**')?s.slice(2,-2):s}))})));
</script>
<template><div class="aa-prose"><p v-for="(line,i) in lines" :key="i" :class="{bullet:line.bullet}"><template v-for="(part,j) in line.text" :key="j"><strong v-if="part.bold">{{part.text}}</strong><template v-else>{{part.text}}</template></template></p><button v-if="long" @click="expanded=!expanded">{{expanded?'收起说明':'展开完整说明'}}</button></div></template>
<style scoped>.aa-prose{font-size:11px;line-height:1.9;color:#708b7b;overflow-wrap:anywhere}.aa-prose p{margin:0 0 9px;white-space:pre-wrap}.aa-prose p.bullet{padding-left:13px;position:relative}.aa-prose p.bullet:before{content:'·';position:absolute;left:2px;color:#8db49b}.aa-prose strong{font-weight:550;color:#527b61}.aa-prose>button{font-size:9px;color:#7b9e87;border-bottom:1px solid #dbe8df;padding:3px 0}</style>
